140	
141	    private final VisitMapper visitMapper;
142	
143	    private final HttpServletRequest request;
144	
145	    /**
146	     * Remembers the owner produced by each previously seen {@code Idempotency-Key}, so a repeated
147	     * create with an already-seen key returns the originally created owner rather than a duplicate.
148	     */
149	    private final Map<String, OwnerDto> idempotencyStore = new ConcurrentHashMap<>();
