233	    /**
234	     * Resolves, validates and maps a create request into a fully-normalized {@link Owner} that is
235	     * ready to persist except for the derived fields assigned by {@link #finalizeOwnerForCreate}. The
236	     * submitted address is canonicalized, the required fields and the optional postcode and
237	     * registration date are validated, and the mapped owner's telephone and email are normalized. The
238	     * registration date is defaulted to the server date when absent and rolled forward to a business
239	     * day. The household id and identity key are derived; a create that would join an already-populated
240	     * household is rejected unless it opts in with {@code sharesHousehold}, and otherwise a soft-match
241	     * duplicate is flagged.
242	     *
243	     * @param ownerFieldsDto the submitted owner fields
244	     * @return the normalized owner, not yet persisted
245	     */
246	    private Owner buildOwnerToCreate(OwnerFieldsDto ownerFieldsDto) {
247	        resolveAddressFields(ownerFieldsDto);
248	        validateRequiredFields(ownerFieldsDto);
249	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
250	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
251	        owner.setTelephone(TelephoneNormalizer.normalize(owner.getTelephone()));
252	        owner.setEmail(normalizeEmail(owner.getEmail()));
253	        validateRegistrationDate(owner.getRegistrationDate());
254	        if (owner.getRegistrationDate() == null) {
255	            owner.setRegistrationDate(LocalDate.now());
256	        }
257	        owner.setRegistrationDate(toBusinessDay(owner.getRegistrationDate()));
258	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
259	        owner.setHouseholdId(HouseholdNormalizer.householdId(owner.getLastName(), owner.getPostcode()));
260	        owner.setIdentityKey(buildIdentityKey(owner));
261	        if (!sharesHousehold) {
262	            rejectHouseholdDuplicate(owner.getHouseholdId());
263	        }
264	        Integer possibleDuplicateOf = sharesHousehold ? null : findPossibleDuplicate(owner);
265	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
266	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
267	        return owner;
268	    }
