270	    /**
271	     * Enforces the per-city and per-day capacity limits for a new owner, in that order. A create that
272	     * would take the owner's city beyond {@link #CITY_OWNER_LIMIT} owners is rejected with a 409, and
273	     * one that would take the owner's registration date beyond {@link #DAILY_OWNER_LIMIT} owners is
274	     * rejected with a 429. The returned count is the number of owners already sharing the owner's
275	     * registration date, measured before it is saved, which the caller uses to decide the response's
276	     * {@code bulkSignupWarning}.
277	     *
278	     * @param owner the normalized owner about to be created
279	     * @return the number of owners already registered on the owner's registration date
280	     */
281	    private long enforceCreateLimits(Owner owner) {
282	        if (countOwnersInCity(owner.getCity()) >= CITY_OWNER_LIMIT) {
283	            throw new OwnerCityFullException(owner.getCity());
284	        }
285	        long ownersRegisteredOnDay = countOwnersRegisteredOn(owner.getRegistrationDate());
286	        if (ownersRegisteredOnDay >= DAILY_OWNER_LIMIT) {
287	            throw new OwnerDailyLimitException(owner.getRegistrationDate());
288	        }
289	        return ownersRegisteredOnDay;
290	    }
