357	    /**
358	     * Rejects an owner payload that is missing or blank in any required field. Collects the name of
359	     * every offending field and, if there is at least one, raises a {@link MissingOwnerFieldsException}
360	     * so the client receives a 400 whose {@code errors} array lists each missing field. The address is
361	     * checked in its resolved form (see {@link #resolveAddressFields}), which is satisfied by either a
362	     * non-blank {@code addressLine1} or the flat {@code address}, so a value that is blank only after
363	     * normalization is still rejected.
364	     *
365	     * @param ownerFieldsDto the submitted owner fields
366	     */
367	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
368	        List<String> missingFields = new ArrayList<>();
369	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
370	            missingFields.add("firstName");
371	        }
372	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
373	            missingFields.add("lastName");
374	        }
375	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
376	            missingFields.add("address");
377	        }
378	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
379	            missingFields.add("city");
380	        }
381	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
382	            missingFields.add("telephone");
383	        }
384	        if (!missingFields.isEmpty()) {
385	            throw new MissingOwnerFieldsException(missingFields);
386	        }
387	    }
