413	    /**
414	     * Validates an owner's optional registration date. Registration date is optional, so a missing
415	     * value is accepted (the create later defaults it to the server date). When a value is supplied
416	     * it may not lie in the future: a date later than the server's current date is rejected with a
417	     * 400 whose {@code errors} array lists {@code registrationDate}.
418	     *
419	     * @param registrationDate the submitted registration date, or {@code null} when none was supplied
420	     * @throws InvalidOwnerFieldsException if a supplied date is later than the server date
421	     */
422	    private void validateRegistrationDate(LocalDate registrationDate) {
423	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
424	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
425	        }
426	    }
