428	    /**
429	     * Rejects a submitted owner that would join a household which already has a member. Because the
430	     * {@code householdId} is derived deterministically from the owner's last name and postcode, any
431	     * existing owner sharing that id is the same household, so a second such owner is reported to the
432	     * client as a 409 Conflict. A request may knowingly bypass this block by opting in with
433	     * {@code sharesHousehold}, in which case this check is not performed.
434	     *
435	     * @param householdId the derived household identifier of the owner about to be created
436	     */
437	    private void rejectHouseholdDuplicate(String householdId) {
438	        boolean duplicate = this.clinicService.findAllOwners().stream()
439	            .filter(existing -> !existing.isDeleted())
440	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
441	        if (duplicate) {
442	            throw new DuplicateOwnerIdentityException(householdId);
443	        }
444	    }
