513	    /**
514	     * Assigns the owner's customer code, formatted {@code <REGION>-<HASH8>}. The region is derived
515	     * from the owner's postcode (falling back to its city), and the code itself - region plus the
516	     * hash of the owner's normalized telephone and last name - is composed by {@link CustomerCode}.
517	     * When the composed code collides with an existing owner's customer code, it is de-duplicated by
518	     * appending {@code -<n>} with the smallest {@code n} of two or more that makes it unique.
519	     *
520	     * @param owner the normalized owner about to be created
521	     * @return the assigned, de-duplicated customer code
522	     */
523	    private String buildCustomerCode(Owner owner) {
524	        String region = OwnerLocality.forPostcodeAndCity(owner.getPostcode(), owner.getCity());
525	        String code = CustomerCode.forRegionAndIdentity(region, owner.getTelephone(), owner.getLastName());
526	        return deduplicateCustomerCode(code);
527	    }
528	
529	    /**
530	     * De-duplicates a freshly composed customer code against the codes of all existing owners. When
531	     * the code is already unique it is returned unchanged; otherwise {@code -<n>} is appended, using
532	     * the smallest {@code n} of two or more that yields a code no existing owner holds.
533	     *
534	     * @param code the composed customer code, before de-duplication
535	     * @return the same code when unique, otherwise the code with the smallest available {@code -<n>} suffix
536	     */
537	    private String deduplicateCustomerCode(String code) {
538	        Set<String> existingCodes = this.clinicService.findAllOwners().stream()
539	            .map(Owner::getCustomerCode)
540	            .filter(existing -> existing != null)
541	            .collect(Collectors.toSet());
542	        if (!existingCodes.contains(code)) {
543	            return code;
544	        }
545	        int suffix = 2;
546	        while (existingCodes.contains(code + "-" + suffix)) {
547	            suffix++;
548	        }
549	        return code + "-" + suffix;
550	    }
