552	    /**
553	     * Counts how many owners already exist that share the supplied first and last name, compared
554	     * case-insensitively. This reflects the number of namesakes present <em>before</em> the current
555	     * owner is created and is stored on the new owner as its {@code namesakeCount}.
556	     *
557	     * @param firstName the submitted owner's first name
558	     * @param lastName the submitted owner's last name
559	     * @return the number of existing owners with the same first and last name, ignoring case
560	     */
561	    private int countNamesakes(String firstName, String lastName) {
562	        return (int) this.clinicService.findAllOwners().stream()
563	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
564	                && lastName.equalsIgnoreCase(existing.getLastName()))
565	            .count();
566	    }
