568	    /**
569	     * Counts how many existing owners already belong to the supplied household, identified by its
570	     * {@code householdId}. Used when creating an owner to determine the household's size once the new
571	     * owner is added (this count plus one).
572	     *
573	     * @param householdId the normalized household identifier of the owner being created
574	     * @return the number of existing owners already sharing that {@code householdId}
575	     */
576	    private int countHouseholdMembers(String householdId) {
577	        return (int) this.clinicService.findAllOwners().stream()
578	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
579	            .count();
580	    }
