582	    /**
583	     * Counts how many owners already live in the supplied city, compared case-insensitively. Used to
584	     * enforce the per-city capacity limit when a new owner is created.
585	     *
586	     * @param city the submitted owner's city
587	     * @return the number of existing owners in that city, ignoring case
588	     */
589	    private long countOwnersInCity(String city) {
590	        return this.clinicService.findAllOwners().stream()
591	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
592	            .count();
593	    }
594	
595	    /**
596	     * Counts how many owners have already been created on the supplied registration date. Used to
597	     * enforce the per-day capacity limit when a new owner is created.
598	     *
599	     * @param registrationDate the registration date of the owner being created
600	     * @return the number of existing owners already registered on that date
601	     */
602	    /**
603	     * Rolls a registration date forward to a business day. A registration date must fall on a
604	     * business day, so when the supplied or defaulted date lands on a Saturday, Sunday or a listed
605	     * public holiday it is moved forward to the next non-holiday weekday; a plain weekday is
606	     * returned unchanged. Every value derived from the registration date (such as the membership
607	     * number's year segment) and the daily create-limit therefore use the adjusted date.
608	     *
609	     * @param date the effective registration date, whether supplied or defaulted to the server date
610	     * @return the same date when it is a business day, otherwise the next non-holiday weekday
611	     */
612	    private LocalDate toBusinessDay(LocalDate date) {
613	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
614	            date = date.plusDays(1);
615	        }
616	        return date;
617	    }
618	
619	    private boolean isWeekend(LocalDate date) {
620	        return date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY;
621	    }
622	
623	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
624	        return this.clinicService.findAllOwners().stream()
625	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
626	            .count();
627	    }
