678	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
679	    @Override
680	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
681	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
682	        if (currentOwner != null) {
683	            Pet currentPet = this.clinicService.findPetById(petId);
684	            if (currentPet != null) {
685	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
686	                currentPet.setName(petFieldsDto.getName());
687	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
688	                this.clinicService.savePet(currentPet);
689	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
690	            }
691	        }
692	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
693	    }
694	
695	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
696	    @Override
697	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
698	        HttpHeaders headers = new HttpHeaders();
699	        Visit visit = visitMapper.toVisit(visitFieldsDto);
700	        Pet pet = new Pet();
701	        pet.setId(petId);
702	        visit.setPet(pet);
703	        this.clinicService.saveVisit(visit);
704	        VisitDto visitDto = visitMapper.toVisitDto(visit);
705	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
706	            .buildAndExpand(visit.getId()).toUri());
707	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
708	    }
709	
710	
711	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
712	    @Override
713	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
714	        Owner owner = this.clinicService.findOwnerById(ownerId);
715	        if (owner != null) {
716	            Pet pet = owner.getPet(petId);
717	            if (pet != null) {
718	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
719	            }
720	        }
